package ktanesolver.module.modded.regular.countdown;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service@ModuleInfo(type=ModuleType.COUNTDOWN,id="countdown",name="Countdown",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Find a legal arithmetic path from six numbers to the three-digit target.",tags={"numbers","arithmetic","timer","countdown"})
public class CountdownSolver extends AbstractModuleSolver<CountdownInput,CountdownOutput>{@Override protected SolveResult<CountdownOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,CountdownInput input){if(input==null||input.numbers()==null||input.numbers().size()!=6||input.numbers().stream().anyMatch(x->x==null||x<1||x>100))return failure("Enter all six positive numbers from 1 to 100");if(input.target()<100||input.target()>999)return failure("Target must be from 100 to 999");CountdownOutput output=calculate(input.numbers(),input.target());return output==null?failure("No legal Countdown solution was found"):success(output);}public static CountdownOutput calculate(List<Integer>numbers,int target){Expr result=solve(numbers,target);if(result==null)return null;List<CountdownOutput.Operation>operations=new ArrayList<>();emit(result,operations);return new CountdownOutput(List.copyOf(operations),format(result),target);}
	@SuppressWarnings("unchecked")static Expr solve(List<Integer>numbers,int target){Map<Integer,Expr>[]dp=new Map[1<<numbers.size()];for(int mask=0;mask<dp.length;mask++)dp[mask]=new LinkedHashMap<>();for(int i=0;i<numbers.size();i++)dp[1<<i].put(numbers.get(i),new Expr(numbers.get(i),null,null,null));for(int size=2;size<=numbers.size();size++)for(int mask=1;mask<dp.length;mask++){if(Integer.bitCount(mask)!=size)continue;for(int aMask=(mask-1)&mask;aMask>0;aMask=(aMask-1)&mask){int bMask=mask^aMask;if(aMask>=bMask)continue;for(Expr a:dp[aMask].values())for(Expr b:dp[bMask].values())combine(dp[mask],a,b);}Expr found=dp[mask].get(target);if(found!=null)return found;}return null;}
	private static void combine(Map<Integer,Expr>out,Expr a,Expr b){add(out,a,b,"+",(long)a.value+b.value);add(out,a,b,"*",(long)a.value*b.value);add(out,a,b,"-",a.value-b.value);add(out,b,a,"-",b.value-a.value);if(b.value!=0&&a.value%b.value==0)add(out,a,b,"/",a.value/b.value);if(a.value!=0&&b.value%a.value==0)add(out,b,a,"/",b.value/a.value);}private static void add(Map<Integer,Expr>out,Expr left,Expr right,String operator,long value){if(value<0||value>9999||operator.equals("/")&&value<=0)return;out.putIfAbsent((int)value,new Expr((int)value,left,right,operator));}private static void emit(Expr expr,List<CountdownOutput.Operation>out){if(expr.operator==null)return;emit(expr.left,out);emit(expr.right,out);out.add(new CountdownOutput.Operation(expr.left.value,expr.operator,expr.right.value,expr.value));}private static String format(Expr expr){return expr.operator==null?String.valueOf(expr.value):"("+format(expr.left)+" "+expr.operator+" "+format(expr.right)+")";}static final class Expr{final int value;final Expr left,right;final String operator;Expr(int value,Expr left,Expr right,String operator){this.value=value;this.left=left;this.right=right;this.operator=operator;}}}
